/// Find the EvolutionChain that contains a given dex number.
/// Returns null if not found.
EvolutionChain? findChainByDex(int dexNumber) {
  try {
    return kAllEvolutionChains.firstWhere(
      (c) => c.stages.any((s) => s.dexNumber == dexNumber),
    );
  } catch (_) {
    return null;
  }
}
